      for (const [k, d] of days) { const [yy, mm] = k.split("-").map(Number); if (yy !== y || mm !== m) continue; imp += d.imp; exp += d.exp; solar += d.solar; n++; }
      const used = Math.max(0, solar + imp - exp), self = Math.max(0, Math.min(solar - exp, used));
