  const t = (s, v) => { let o = ngLang() === "de" ? s : (EN[s] ?? s); if (v) for (const [k, x] of Object.entries(v)) o = o.split(`{${k}}`).join(String(x)); return o; };
  const numLoc = () => (ngLang() === "de" ? "de-DE" : (ngH?.locale?.language || "en"));
