      if (p.key === "kameras" && cc > 1) sec.cards = sec.cards.map((c) => (c.type === "picture-entity" ? { ...c, grid_options: { columns: (12 * w) / cc } } : c));
      if (hass) withExtras(sec, p.key, L, hass, "home");
      if (p.from) names[p.key] = L.names?.[p.key] || p.name;
