      <div class="list">${gl.map(([k, n]) => `<button class="it" data-g="${esc(k)}"><ha-icon icon="mdi:arrow-right-bold-box-outline"></ha-icon><span class="t"><span>${esc(n)}</span></span></button>`).join("")}</div>
